static pthread_once_t pool_once = PTHREAD_ONCE_INIT;
static db_pool_t *pool;

static void acquire(void) {
    pool = db_pool_open(cfg, /*min_idle=*/8);
    if (!pool) { log_fatal("pool acquisition failed"); exit(EXIT_FAILURE); }
}

int main(void) {
    pthread_once(&pool_once, acquire);   /* acquired before the first request */
    serve(pool);
}
